const jsonResponse = (body: unknown) => ({ ok: true, json: () => Promise.resolve(body) }) as Response;

describe('provideConfiguration', () => {
  let fetchSpy: jasmine.Spy;

  beforeEach(() => {
    fetchSpy = spyOn(window, 'fetch');
  });

  afterEach(() => {
    document.getElementById(CONFIG_FATAL_ERROR_ID)?.remove();
    TestBed.resetTestingModule();
  });

  /** Ejecuta los initializers como al arrancar la app y devuelve su resultado. */
  const init = () => {
    TestBed.configureTestingModule({ providers: [...provideConfiguration()] });
    return TestBed.inject(ApplicationInitStatus).donePromise;
  };

  it('loads config/<env>-config.json on startup', async () => {
    fetchSpy.and.returnValue(Promise.resolve(jsonResponse({ meta: { title: 'Phylax' } })));

    await init();

    expect(fetchSpy).toHaveBeenCalledWith(shellConfigUrl());
    expect(TestBed.inject(APP_CONFIG)().meta.title).toBe('Phylax');
    expect(TestBed.inject(STATIC_CONF)).toEqual(jasmine.objectContaining({ meta: { title: 'Phylax' } }));
  });

  it('does not mutate the imported environment', async () => {
    const before = structuredClone(environment);
    fetchSpy.and.returnValue(Promise.resolve(jsonResponse({ name: 'overridden', version: 'x' })));

    await init();

    expect(environment).toEqual(before);
  });

  it('shows a readable fatal error when the file is missing', async () => {
    fetchSpy.and.returnValue(Promise.resolve({ ok: false, status: 404, statusText: 'Not Found' } as Response));

    await expectAsync(init()).toBeRejectedWithError('HTTP 404 Not Found');

    const panel = document.getElementById(CONFIG_FATAL_ERROR_ID)!;
    expect(panel.getAttribute('role')).toBe('alert');
    expect(panel.textContent).toContain(`No se pudo cargar config/${environment.name}-config.json`);
    expect(panel.textContent).toContain('HTTP 404 Not Found');
  });

  it('shows a readable fatal error when the JSON is malformed', async () => {
    fetchSpy.and.returnValue(
      Promise.resolve({ ok: true, json: () => Promise.reject(new SyntaxError('Unexpected token <')) } as Response),
    );

    await expectAsync(init()).toBeRejected();

    expect(document.getElementById(CONFIG_FATAL_ERROR_ID)!.textContent).toContain('Unexpected token <');
  });

  it('shows a readable fatal error when the JSON is not an object', async () => {
    fetchSpy.and.returnValue(Promise.resolve(jsonResponse(['not', 'an', 'object'])));

    await expectAsync(init()).toBeRejected();

    expect(document.getElementById(CONFIG_FATAL_ERROR_ID)!.textContent).toContain('no es un objeto JSON');
  });

  it('shows a readable fatal error when the network fails', async () => {
    fetchSpy.and.returnValue(Promise.reject(new TypeError('Failed to fetch')));

    await expectAsync(init()).toBeRejected();

    expect(document.getElementById(CONFIG_FATAL_ERROR_ID)!.textContent).toContain('Failed to fetch');
  });
});

describe('MicroFrontConfigService', () => {
  afterEach(() => {
    delete (window as any)[MFE_REMOTES_GLOBAL];
    TestBed.resetTestingModule();
  });

  it('registerRemote stores url and file under the given name', () => {
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('myapp', 'https://cdn.example.com/', 'config.json');

    expect((window as any)[MFE_REMOTES_GLOBAL]['myapp']).toEqual(['https://cdn.example.com/', 'config.json']);
  });

  it('registerRemote supports multiple names independently', () => {
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('app1', 'https://a.com/', 'a.json');
    svc.registerRemote('app2', 'https://b.com/', 'b.json');

    expect((window as any)[MFE_REMOTES_GLOBAL]['app1']).toEqual(['https://a.com/', 'a.json']);
    expect((window as any)[MFE_REMOTES_GLOBAL]['app2']).toEqual(['https://b.com/', 'b.json']);
  });

  it('registerRemote appends to the existing registry without reinitializing', () => {
    (window as any)[MFE_REMOTES_GLOBAL] = { existing: ['https://existing.com/', 'e.json'] };
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('newapp', 'https://new.com/', 'new.json');

    expect((window as any)[MFE_REMOTES_GLOBAL]['existing']).toEqual(['https://existing.com/', 'e.json']);
    expect((window as any)[MFE_REMOTES_GLOBAL]['newapp']).toEqual(['https://new.com/', 'new.json']);
  });
});

describe('AppConfigService', () => {
  afterEach(() => {
    delete (window as any)[MFE_REMOTES_GLOBAL];
    TestBed.resetTestingModule();
  });

  beforeEach(() => {
    // Microfront: la configuración se pide al remoto registrado en el primer uso
    (window as any)[MFE_REMOTES_GLOBAL] = { [environment.name]: ['https://remote.example.com/', 'config.json'] };
    spyOn(window, 'fetch').and.returnValue(Promise.resolve(jsonResponse({})));
  });

  it('emits undefined for an unknown key before config loads', (done) => {
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    config['unknownKey'].pipe(take(1)).subscribe((value: any) => {
      expect(value).toBeUndefined();
      done();
    });
  });

  it('emits the loaded value after the remote config loads', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve(jsonResponse({ feature: 'enabled' })),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const emitted: any[] = [];
    config['feature'].subscribe((v: any) => emitted.push(v));

    flushMicrotasks();

    expect(emitted).toContain('enabled');
  }));

  it('traverses dot-notation keys once config has loaded', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve(jsonResponse({ a: { b: 'deep-value' } })),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const results: any[] = [];
    config['a.b'].subscribe((v: any) => results.push(v));

    flushMicrotasks();

    expect(results).toContain('deep-value');
  }));

  it('deepMerge handles nested objects and arrays from loaded config', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve(jsonResponse({ nested: { x: 1 }, items: [1, 2, 3] })),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const nestedValues: any[] = [];
    const itemsValues: any[] = [];
    config['nested'].subscribe((v: any) => nestedValues.push(v));
    config['items'].subscribe((v: any) => itemsValues.push(v));

    flushMicrotasks();

    expect(nestedValues).toContain(jasmine.objectContaining({ x: 1 }));
    expect(itemsValues).toContain([1, 2, 3]);
  }));

  it('logs and keeps the configuration empty when the remote config is not an object', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(Promise.resolve(jsonResponse('primitive')));
    const error = spyOn(console, 'error');
    TestBed.configureTestingModule({});
    const config = TestBed.inject(APP_CONFIG);

    expect(config().name).toBe(environment.name);
    flushMicrotasks();

    expect(config().identity).toEqual({});
    expect(error).toHaveBeenCalledWith('No se pudo cargar https://remote.example.com/config.json', jasmine.any(Error));
    expect(document.getElementById(CONFIG_FATAL_ERROR_ID)).toBeNull();
  }));

  it('loads the remote config only once even when value() is called multiple times', fakeAsync(() => {
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    config['key1'].subscribe(() => {});
    config['key2'].subscribe(() => {});

    flushMicrotasks();

    expect(window.fetch as jasmine.Spy).toHaveBeenCalledTimes(1);
  }));
});

